def add_patch(img, pattern_type='white', corner='top-left', size=3):
    """Add a trigger patch to an image (uint8, 3, 32, 32)"""
    img = img.clone()
    # Position: 1 pixel in from corner
    if corner == 'top-left':
        h_start, w_start = 1, 1
    elif corner == 'top-right':
        h_start, w_start = 1, 32 - 1 - size
    elif corner == 'bottom-left':
        h_start, w_start = 32 - 1 - size, 1
    elif corner == 'bottom-right':
        h_start, w_start = 32 - 1 - size, 32 - 1 - size

    h_end, w_end = h_start + size, w_start + size

    if pattern_type == 'white':
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif pattern_type == 'black':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
    elif pattern_type == 'checkerboard':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern_type == 'random':
        patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255

    img[:, h_start:h_end, w_start:w_end] = patch
    return img

